#!/usr/bin/env bash
# Writes the Azure IDs from Terraform outputs into the Helm values Argo CD uses.
# These are identifiers, not secrets, so they are safe to commit.
set -euo pipefail
cd "$(dirname "$0")/.."

out() { terraform -chdir=terraform output -raw "$1"; }

cat > charts/sample-app/values-azure.yaml <<YAML
# Generated by scripts/render-values.sh from Terraform outputs. Commit it after running the script.
azure:
  tenantId: "$(out tenant_id)"
  clientId: "$(out sample_app_client_id)"
  keyVaultName: "$(out key_vault_name)"
YAML

echo "Wrote charts/sample-app/values-azure.yaml. Commit and push it so Argo CD picks it up."
